document.addEventListener("alpine:init",()=>{class CartItem{constructor(data){this.pid=parseInt(data.pid);this.variation=data.variation}}
Alpine.data("rccart",()=>({items:[],init(){if(RockCommerce.cart)return;console.log("init cart");RockCommerce.addComponent(this);RockCommerce.cart=this;this.wakeup();this.$watch("items",this.update.bind(this));this.update()},add(data){RockCommerce.trigger("addToCart",data,(data)=>{const item=new CartItem(data);while(data.amount>0){this.items.push(item);data.amount--}})},get count(){return this.items.length},sleep(){const data={items:this.items,};localStorage.setItem("rc-cart",JSON.stringify(data))},update(){RockCommerce.debounce("rc-cart-update",()=>{this.updateCartCountElements();this.sleep()})},updateCartCountElements(){let elements=document.querySelectorAll("[rc-cart-count]");elements.forEach((el)=>{el.textContent=this.count;if(this.count>0)el.removeAttribute("hidden");else el.setAttribute("hidden",!0)})},wakeup(){const data=localStorage.getItem("rc-cart")||"{}";const parsedData=JSON.parse(data);for(const key in parsedData){if(parsedData.hasOwnProperty(key)){this[key]=parsedData[key]}}},}))})